# R/raster-info.R
# Manual file - NOT generated by orchestrate.R
# The GDALRasterBand class and what a band knows about itself.

# ============================================================================
# GDALRasterBand S7 class
#
# What a band knows about itself is a property rather than a verb. Every one
# of them is read from GDAL at the moment it is asked for, so a property is
# never a stale copy taken when the object was made, and the ones GDAL lets
# you change are settable the same way they are read.
# ============================================================================

#' GDALRasterBand class
#'
#' Represents a raster band within a GDAL dataset. Its properties are read
#' from GDAL each time, and the ones a dataset open for writing can change are
#' settable:
#'
#' * `xsize`, `ysize`, `band_number`, `block_size`, read only.
#' * `data_type`, its GDAL code, and `data_type_name`, read only.
#' * `nodata_value`, `scale`, `offset`, `unit_type`, settable.
#' * `color_interpretation`, settable, and `color_interpretation_name`.
#' * `overview_count` and `overview_sizes`, read only.
#'
#' A `nodata_value` of NULL means the band has none, and assigning NULL takes
#' the value off the band, which is a different thing from setting it to NaN.
#' Scale and offset are how a band of integers carries real values: the value
#' meant is `raw * scale + offset`, which GDAL records but does not apply, so
#' [read_raster()] returns the raw numbers.
#'
#' @param .ptr Internal. External pointer to the underlying GDAL object.
#' @export
#' @examples
#' ds <- gdal_open(system.file("extdata/test.tif", package = "GDAL7"))
#' band <- get_raster_band(ds, 1)
#'
#' c(band@xsize, band@ysize)
#' band@data_type_name
#' band@block_size
#'
#' gdal_close(ds)
GDALRasterBand <- S7::new_class(
    "GDALRasterBand",
    parent = GDALMajorObject,

    # A band is built from a GDAL handle and nothing else. S7's default
    # constructor would take one argument per settable property and assign
    # every one of them at construction, calling the setters with an empty
    # value, so the constructor is written out here.
    constructor = function(.ptr) {
        S7::new_object(GDALMajorObject(.ptr = .ptr), .ptr = .ptr)
    },

    properties = list(
        .ptr = S7::class_any,

        xsize = S7::new_property(
            S7::class_integer,
            getter = function(self) GDAL7_band_get_xsize(self@.ptr)
        ),
        ysize = S7::new_property(
            S7::class_integer,
            getter = function(self) GDAL7_band_get_ysize(self@.ptr)
        ),
        band_number = S7::new_property(
            S7::class_integer,
            getter = function(self) GDAL7_band_get_band_number(self@.ptr)
        ),

        data_type = S7::new_property(
            S7::class_integer,
            getter = function(self) GDAL7_band_get_data_type(self@.ptr)
        ),
        data_type_name = S7::new_property(
            S7::class_character,
            getter = function(self) GDAL7_band_get_data_type_name(self@.ptr)
        ),

        block_size = S7::new_property(
            S7::class_integer,
            getter = function(self) GDAL7_band_get_block_size(self@.ptr)
        ),

        nodata_value = S7::new_property(
            S7::class_any,
            getter = function(self) GDAL7_band_get_nodata_value(self@.ptr),
            setter = function(self, value) {
                GDAL7_band_set_nodata_value(
                    self@.ptr, if (is.null(value)) NULL else as.double(value)
                )
                self
            }
        ),
        scale = S7::new_property(
            S7::class_any,
            getter = function(self) GDAL7_band_get_scale(self@.ptr),
            setter = function(self, value) {
                GDAL7_band_set_scale(self@.ptr, as.double(value))
                self
            }
        ),
        offset = S7::new_property(
            S7::class_any,
            getter = function(self) GDAL7_band_get_offset(self@.ptr),
            setter = function(self, value) {
                GDAL7_band_set_offset(self@.ptr, as.double(value))
                self
            }
        ),
        unit_type = S7::new_property(
            S7::class_character,
            getter = function(self) GDAL7_band_get_unit_type(self@.ptr),
            setter = function(self, value) {
                GDAL7_band_set_unit_type(self@.ptr, as.character(value))
                self
            }
        ),

        color_interpretation = S7::new_property(
            S7::class_any,
            getter = function(self) GDAL7_band_get_color_interpretation(self@.ptr),
            setter = function(self, value) {
                GDAL7_band_set_color_interpretation(self@.ptr, as.character(value))
                self
            }
        ),
        color_interpretation_name = S7::new_property(
            S7::class_character,
            getter = function(self) GDAL7_band_get_color_interpretation_name(self@.ptr)
        ),

        overview_count = S7::new_property(
            S7::class_integer,
            getter = function(self) GDAL7_band_get_overview_count(self@.ptr)
        ),
        overview_sizes = S7::new_property(
            S7::class_any,
            getter = function(self) band_overview_sizes(self)
        )
    )
)

# ============================================================================
# Dataset accessor for a band
# ============================================================================

#' Get a raster band from a dataset
#'
#' A band is taken by number, so this is a function rather than a property.
#' What the band then knows about itself is a property of the band; see
#' [GDALRasterBand].
#'
#' @param x A GDALDataset object
#' @param nBand Band number, 1-indexed
#' @return A GDALRasterBand object
#' @export
#' @examples
#' ds <- gdal_open(system.file("extdata/test.tif", package = "GDAL7"))
#' get_raster_band(ds, 1)
#' gdal_close(ds)
get_raster_band <- S7::new_generic("get_raster_band", "x", function(x, nBand) S7::S7_dispatch())

S7::method(get_raster_band, GDALDataset) <- function(x, nBand) {
    ptr <- GDAL7_dataset_get_band(x@.ptr, as.integer(nBand))
    GDALRasterBand(.ptr = ptr)
}

# ============================================================================
# Print method for GDALRasterBand
# ============================================================================

#' @export
S7::method(print, GDALRasterBand) <- function(x, ...) {
    cat("<GDALRasterBand>\n")
    cat("  Band:       ", x@band_number, "\n", sep = "")
    cat("  Size:       ", x@xsize, " x ", x@ysize, "\n", sep = "")
    cat("  Type:       ", x@data_type_name, "\n", sep = "")

    block <- x@block_size
    cat("  Block size: ", block["x"], " x ", block["y"], "\n", sep = "")

    nodata <- x@nodata_value
    if (!is.null(nodata)) {
        cat("  NoData:     ", nodata, "\n", sep = "")
    }

    desc <- x@description
    if (nchar(desc) > 0) {
        cat("  Description:", desc, "\n")
    }

    color <- x@color_interpretation_name
    if (nchar(color) > 0 && color != "Undefined") {
        cat("  Color:      ", color, "\n", sep = "")
    }

    invisible(x)
}
